How to set table to persist.

                  UserGroup = new ICS.Database.TableObjects.RFS.RFS_UserGroup(DataAccess,"");
                  UserGroup.UserID = UserID;
                  UserGroup.EnvironmentID = EnvironmentID;
                  DataAccess.TablesToPersist.Add(_UserGroup);

Sets Business data connection based on environment settings.


             string EnvironmentID = "TEST";

             //Table object for RFS_Environment system table
             _Environment = new ICS.Database.TableObjects.RFS.RFS_Environment(DataAccessLayer, "");
               _Environment.EnvironmentID = EnvironmentID;
               _Environment.Fetch();

               //Settings column contains XML of environment settings.
             UserConfig = new ICS.Utilities.Configuration(_Environment.Settings, EnvironmentID);

             DataAccessLayer.SetDataDBConnection(UserConfig);

