member.example:
Use of Query and DataReader.

            DataAccess.System.Query = "Select Count(TxId) From RFS_TxHeader";
            if (DataAccess.System.DataReader.Read())
            {
              int Count = Convert.ToInt32(DataAccess.System.DataReader.GetValue(0));
            }

Use of Query and DataReader.

            DataAccess.System.Query = "Select Count(TxId) From RFS_TxHeader";
            if (DataAccess.System.DataReader.Read())
            {
              int Count = Convert.ToInt32(DataAccess.System.DataReader.GetValue(0));
            }

Code Snippet shows use of ExecuteInsert

             public void Insert(Hashtable Values)
             {
                  int RowsAffected = DbConnection.ExecuteInsert("TxHeader", Values, "select @@identity");

                  if (RowsAffected > 0)
                  {
                     if (DbConnection.DataReader.Read())
                     {
                        //Only one column returned
                        int IdentityValue = DbConnection.DataReader.GetInt32(0);
                     }
                  }
             }

Code Snippet shows use of ExecuteInsert

             public void Insert(Hashtable Values)
             {
                  int RowsAffected = DbConnection.ExecuteInsert("TxHeader", Values, "select @@identity");

                  if (RowsAffected > 0)
                  {
                     if (DbConnection.DataReader.Read())
                     {
                        //Only one column returned
                        int IdentityValue = DbConnection.DataReader.GetInt32(0);
                     }
                  }
             }

Use of BeginTransaction with RFSmart DataAccess.

             //ICS.Database.DAL DataAccess defined earlier
             DataAccess.System.BeginTransaction();
             bool UpdateFailed = false;
             for (int i=0;i<10;i++)
             {
               int RowsAffected =
                     DataAccess.System.NonQuery("Update SomeTable set Flag = 1 Where Id = " + i);

               if (RowsAffected == 0)
               {
                  DataAccess.System.EndTransaction(false);
                  return;
               }
             }

             DataAccess.System.EndTransaction(true);

member.summary:
Logs table data based on the name of the table provided.  The data is written as XML.
If the table is a system table, the data will only be written if logging is set to 4;
otherwise, 3.

member.remarks:
ex: "Database=[Database Name];Server=[Server Name];User Id=[User];
            Password=[Password];Max Pool Size=[Max Pool Size];"  If Integrated Security is
            enabled, the user id and password are replaced with "Integrated Security=True;"

